M.TYPED_SELFTRY_R40=M.TYPED_SELFTRY_R40||{};
var D=M.__r40draft=M.__r40draft||{};
function E(t){return String(t==null?'':t).replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];});}
function num(s){s=String(s==null?'':s).trim().replace(/\u2212/g,'-');/* R104 (R103-ASM-02): nur aeusserer Leerraum; '0 6' ist keine Zahl */return /^[+-]?(\d+([.,]\d*)?|[.,]\d+)$/.test(s)?Number(s.replace(',','.')):null;}
